input[type='time'],
input[type='datetime-local'] {
  /* Remove iOS WKWebView native chrome that overrides our styling */
  -webkit-appearance: none;
  -moz-appearance: none;
       appearance: none;
  /* Lock to the same height as our base Input component on mobile */
  box-sizing: border-box;
  min-height: 3rem;
  height: 3rem;
  /* !important overrides Tailwind utility layer (py-3) which would otherwise
     win the cascade and expand the input height on iOS WKWebView */
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  /* Vertically centre the date/time text within the fixed height */
  line-height: 3rem;
  /* Ensure text doesn't overflow on narrow screens */
  overflow: hidden;
